<?php

namespace Agent\AgentBundle\Repository;

use Doctrine\ORM\Query\Expr\Join;

/**
 * ExerciceRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ExerciceRepository extends \Doctrine\ORM\EntityRepository {

    public function exerciceActif($matricule) {


        $QueryBuilder = $this->createQueryBuilder('ex')
                ->innerJoin('AgentBundle:Decision', 'dec', Join::WITH, 'dec.exercice = ex.id')
                ->innerJoin('AgentBundle:DecisionAgent', 'decag', Join::WITH, 'decag.decision = dec.id')
                ->innerJoin('decag.agent', 'agent')
                ->leftJoin('AgentBundle:Conges', 'conge', Join::WITH, 'conge.exercice = dec.exercice and conge.typeConges=1 and decag.agent= :matricule')
                ->where('agent.matricule = :matricule')
                ->andWhere('conge.id is null')
                ->orderBy('ex.id', 'DESC')
                //->andWhere('ex.annee = :annee')
                ->setParameter('matricule', $matricule->getMatricule())
                //->setParameter('annee', $annee)
                ->setMaxResults(1);

        return $QueryBuilder;
    }

}
